"""Create an auditable inventory rather than asserting unnamed coverage."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
    rows=[]
    def add(names,source,paths,status='implemented',note=''):
        for p in paths.split(';'):assert (ROOT/p).is_file(),p
        for name in names.split('|'):rows.append({'topic':name,'lecture':source,'status':status,'evidence':paths.split(';'),'scope':note})
    add('ML parameters and losses|MSE/cross-entropy/hinge|L0/L1/L2 regularization|Continuous/discrete variables|Convex/nonconvex landscapes|Local/global minima and saddle','PPT1 2-9,20,27','tracks/A/contopt/problems.py;tracks/A/results/supplementary.json')
    add('GD|SGD|Mini-batch SGD|Momentum|Nesterov|AdaGrad|RMSProp|Adam|Newton|Gauss-Newton','Assignment 5 / PPT1 10-21','tracks/A/contopt/optimizers.py;tracks/A/results/raw_runs.json')
    add('Backpropagation distinct from optimizer|Finite-difference gradient checks','PPT1 11','tracks/A/contopt/problems.py;tracks/A/tests/test_continuous.py')
    add('Convex/strongly-convex bounds|Nonconvex stationarity|Step-size tuning|Noisy gradient objectives|Expected versus empirical Fisher|Diagonal curvature|Low-rank curvature|Matrix-free HVP/CG|L-BFGS library demo','Assignment 5 / PPT1 20 / PPT4 4-6','tracks/A/contopt/supplement.py;tracks/A/results/supplementary.json')
    add('Density greedy|Binary ILP|Branch-and-Bound|Dynamic programming','Assignment 5 / PPT1 26','tracks/B/discopt/solvers.py;tracks/B/results/raw_runs.json')
    add('Forward feature selection|Backward feature elimination|Exhaustive feature reference|QUBO constraint penalties|Binary-to-spin Ising conversion','PPT1 23-27 / Assignment 5','tracks/B/discopt/supplement.py;tracks/B/discopt/qubo.py;tracks/B/results/supplementary.json')
    add('Submodularity and diminishing returns|Monotonicity/normalization|Greedy cardinality guarantee assumptions|Lazy greedy|Failed-assumption control','PPT1 29-34','tracks/D/distopt/coverage.py;tracks/D/results/coverage_controls.json')
    add('Static blocks|LPT scheduling|Dynamic task pool|Work stealing|Makespan|Strong/weak scaling|Amdahl and Gustafson interpretation','PPT2 6-15','tracks/D/distopt/scheduling.py;tracks/D/results/summary.json',note='Actual CPU processes; steady and total clocks are separate.')
    add('Storage-order traversal|Tiled traversal|Locks versus reduction|Local IPC batching','PPT2 16-27','tracks/D/distopt/locality.py;tracks/D/results/locality_runs.json;tracks/D/results/synchronization_runs.json',note='No hardware cache counters or network-cluster claim.')
    add('Data parallelism|Model/tensor parallelism|Pipeline microbatches','PPT4 8-14','tracks/D/distopt/parallel.py;tracks/D/results/parallel_runs.json',note='Actual shared-memory CPU forward inference, not multi-GPU training.')
    add('FedAvg versus matched centralized GD|MGDA|GradNorm','Assignment 5/D','tracks/D/distopt/federated.py;tracks/D/distopt/multitask.py;tracks/D/results/multitask_runs.json',note='Federated clients are serially emulated; no distributed wall-time claim.')
    add('Grid search|Random search|Bayesian expected-improvement search|Successive halving|ASHA promotion scheduling','PPT4 17-18,27','chapter_supplement/study.py;chapter_supplement/results/hpo.json','numerical_demo','Actual learning curves, policy replay; ASHA clock is offline event simulation.')
    add('Top-k sparsification|Error feedback|Int8 gradient compression|Low-rank activation approximation','PPT4 15 / PPT2 33','chapter_supplement/study.py;chapter_supplement/results/compression.json',note='Toy optimization; logical payload only. Not OFLight/Subspace Networks.')
    add('Hybrid-layout enumeration|Genetic layout search|PSO black-box control','PPT4 4-7,16','chapter_supplement/study.py;chapter_supplement/results/layouts.json','numerical_demo','Fictional layout model; separate bounded Rastrigin PSO. Not EAHP/Astra.')
    add('Cyclic scheduling|Guided scheduling','PPT2 12','chapter_supplement/study.py;chapter_supplement/results/scheduling.json','numerical_demo','Discrete-event scheduling, zero dispatch overhead.')
    add('False sharing and padding|Atomic increments','PPT2 20-24','chapter_supplement/false_sharing.c;chapter_supplement/results/false_sharing.json',note='Two real OpenMP threads; no cache-coherence counters.')
    add('NUMA/local placement|Race interleavings|Deadlock and ordered locks|Broadcast/scatter/gather/reduce/allreduce semantics|Stale-gradient effects|Overlap arithmetic|Weight quantization|Magnitude pruning|Discrete architecture choices','PPT1 28 / PPT2 20-28 / PPT4 11-15','chapter_supplement/study.py;chapter_supplement/results/foundations.json','numerical_demo','Finite models/toy matrices; no actual MPI, NUMA hardware, trained NAS or asynchronous cluster timing.')
    add('VQE|QAOA with B QUBO|PQC|QNN/VQC|Parameter-shift|SPSA|Quantum natural gradient','Assignment 5/C / PPT3 18-30','tracks/C/qopt/models.py;tracks/C/qopt/optimizers.py;tracks/C/results/vqe_runs.json',note='CPU simulator; QNG metric uses exact amplitudes.')
    add('Finite-shot measurement cost|Generic hardware-noise effects|Barren-plateau diagnostics','PPT3 6-8,19,32','tracks/C/results/shot_study.json;tracks/C/results/noise_study.json;tracks/C/results/barren_plateaus.json',note='Finite empirical diagnostics, not a universal asymptotic proof.')
    add('Deutsch|Deutsch-Jozsa|Bernstein-Vazirani|Grover|QFT|QPE|Shor toy order finding|Qubits/gates/entanglement|Quantum annealing','Assignment 5/I / PPT3 3-18','tracks/I/qstudy/circuits.py;tracks/I/results/algorithm_runs.json;tracks/I/results/annealing_runs.json',note='Explicit small circuits; dense toy arithmetic and gate-based annealing, not scalable factoring or physical annealer.')
    add('Quantum kernel versus matched RBF learner|Hardware-calibrated noise|Query/gate/wall-time accounting','Assignment I','tracks/I/qstudy/learning.py;tracks/I/results/qml_runs.json;tracks/I/results/noise_provenance.json;tracks/I/results/grover_runs.json')
    add('Minor embedding and chain penalties|Coefficient rescaling and physical-qubit overhead','Assignment 5','chapter_supplement/study.py;chapter_supplement/results/embedding.json','numerical_demo','Exact 16-state classical enumeration, no annealer hardware.')
    for l,name,code in [('E','Main EV case: binary cost scheduling','evcharge/solvers.py'),('F','Compiler: frontend/IR/backend, four passes and DP ordering','toycc/search.py'),('G','Real xv6: page allocation and cache lookup','patches/track_g.patch'),('H','Real SQLite: budgeted index portfolios','dblab/select.py'),('J','Real software: test selection and fault trade-off','selci/selection.py')]:add(name,'Assignment Track '+l,f'tracks/{l}/{code};tracks/{l}/results/summary.json')
    registry=json.loads((ROOT/'research_supplement/SOURCE_REGISTRY.json').read_text())
    refs=[{'topic':r['topic'],'lecture':r['lecture'],'url':r['primary_url'],'source_status':'source_and_scope_recorded','experiment_status':r['fidelity'],'evidence':[r['code'],r['result']],'scope':r['scope'],'full_paper_reproduction':False,'remaining_exact_method_gap':r.get('remaining_exact_method_gap',False)} for r in registry['entries']]
    data={'topics':rows,'research_references':refs,'fidelity_counts':registry['fidelity_counts'],'strict_paper_method_coverage_complete':False,'interpretation':'All 23 research entries have experiments or controls. Eleven scoped source ports, four algorithm variants, two survey demonstrations and six mechanism-only controls are distinguished; no entire paper or source-scale performance is reproduced.'}
    (ROOT/'docs/CHAPTER6_CHECKLIST.json').write_text(json.dumps(data,indent=2)+'\n')
    s='# Chapter 6 evidence checklist\n\nThe root status supersedes historical per-track progress notes. Numerical models are not hardware experiments.\n\n| Topic | Lecture | Status | Evidence | Scope |\n|---|---|---|---|---|\n'
    for r in rows:s+='| '+r['topic']+' | '+r['lecture']+' | '+r['status']+' | '+', '.join('`'+p+'`' for p in r['evidence'])+' | '+r['scope']+' |\n'
    s+='\n## Research extension and remaining boundary\n\nAll 23 entries now have executable experiments or controls. A source port means only its stated small equation/code specialization. The six mechanism-only entries lack publicly retrieved detailed policies; they do not close a strict exact-method requirement. See research_supplement/METHOD_COVERAGE.md for every adaptation and source locator. No full paper performance reproduction is claimed.\n\n| Entry | Lecture | Fidelity | Evidence | Scope |\n|---|---|---|---|---|\n'
    for r in refs:s+='| '+r['topic']+' | '+r['lecture']+' | '+r['experiment_status']+' | '+', '.join('`'+p+'`' for p in r['evidence'])+' | '+r['scope']+' |\n'
    s+='\nNames explicitly marked not found/not cited in the slides are not fabricated: DiCTR, Mixer, RLDPSO, AutoHAAP, SSGS, OSCAR, LS-GT and AFS-GNN.\n'
    (ROOT/'docs/CHAPTER6_CHECKLIST.md').write_text(s);print(len(rows),'topic entries;',len(refs),'research entries')
if __name__=='__main__':main()
